  "Open an emotion example": "感情実験のサンプルを開く",
  "Explore the workspace": "ワークスペースを見る",
  "Advanced reference": "詳細リファレンス",
  "Add a step, set its content, then run a test. Freeze a version before formal collection.": "手順を追加し、内容を設定してテストしてください。本番の前にバージョンを凍結します。",
  "Create and edit": "実験を作成・編集",
  "Create a blank protocol or choose an Emotion, Stroop or Go/No-Go template.": "ホームで空の実験、または感情・Stroop・Go/No-Go テンプレートを選びます。",
  "Select a step, then click a component on the left to add the next step.": "手順を選択し、左の要素をクリックして次の手順を追加します。",
  "Set content, duration and responses on the right. Use the flow graph for branches.": "右で刺激、時間、回答方法を設定します。分岐はフロー図を使います。",
  "Save, then choose Preview run with a test participant to check the content.": "保存後にテスト実行し、テスト用の参加者で内容を確認します。",
  "Drafts can run tests. Freeze for formal collection; create an editable version to make changes.": "テストにはドラフトを使えます。本番には凍結版を使い、修正には編集可能な版を作成します。",
  "Prepare participants and devices": "参加者と機器を準備",
  "Choose Preview run in the editor or prepare collection from a frozen version.": "編集画面でテスト実行、または凍結版から収集を準備します。",
  "Enter participant ID and language, then check media and the data destination.": "参加者 ID、言語、メディア、保存先を確認します。",
  "Start the acquisition service and check fresh signals on every required channel.": "計測サービスを起動し、必要な全チャンネルの信号を確認します。",
  "Keep the operator monitor on the operator display and the experiment on the participant display.": "管理者モニターを管理者画面、実験ウィンドウを参加者画面に置きます。",
  "For missing signals, check devices, electrodes, the acquisition service and connection address. Formal collection needs real devices and writable storage.": "欠損時は機器、電極、計測サービス、接続先を確認してください。本番には実機と書込可能な保存先が必要です。",
  "Run and verify": "実行と DB 検証",
  "Confirm the run details and signals, then begin the experiment.": "実行情報と信号を確認して実験を開始します。",
  "Participants see stimuli and questions; operators monitor and pause or resume separately.": "参加者は刺激と質問に回答し、管理者は別画面で監視・一時停止します。",
  "At completion, confirm that session data was saved, then export the complete package.": "終了後に保存成功を確認し、完全なデータパッケージを出力します。",
  "When PhysioDB test verification is enabled, wait for upload and database read-back checks.": "PhysioDB テスト検証を有効にした場合、送信と読戻しの完了を待ちます。",
  "Local saving and database verification are separate. Tests without devices explicitly use a synthetic signal. Formal raw recordings currently require explicit upload.": "ローカル保存と DB 検証は別の状態です。機器なしのテスト信号は合成と表示されます。本番の生データは明示的にアップロードします。",
  "Review and analyze": "記録と分析",
  "Open Sessions in the workspace and select the participant record.": "ホームの実験記録で対象の参加者を選びます。",
  "Review saving, events and the PhysioDB verification report.": "保存状態、イベント、PhysioDB 検証結果を確認します。",
  "Analyze this session to inspect the timeline and answers; return to the same saved record.": "この実験記録を分析し、時間線や回答を確認します。戻ると同じ記録を開きます。",
  "Database reads database time windows, displays waveforms and statistics, and exports CSV.": "データベースで DB の時間窓を読み、波形・統計・CSV を確認します。",
  "Save researcher notes and validity reviews. Automatic integrity checks do not replace researcher judgment.": "研究者のメモと有効性評価を保存できます。自動チェックは研究者の判断を置き換えません。",
  "▶ Preview media": "▶ メディアをプレビュー",
  "▼ Hide preview": "▼ プレビューを閉じる",
