  "Default desktop data folder": "デスクトップ版の既定データフォルダー",
  "Default trial layout": "試行の既定レイアウト",
  "Extra large (1.15x)": "特大 (1.15x)",
  "Failed to save asset:": "アセットの保存に失敗しました：",
  "Font family": "フォント",
