  "Session ZIP contents": "セッション ZIP の内容",
  "Storage & sharing": "保存と共有",
  "Stored locally with SHA-256 checksum": "SHA-256 チェックサム付きでローカルに保存します",
  "System UI (default)": "システムフォント（既定）",
  "THEME SETTINGS": "テーマ設定",
