  "Exports are local files. CSV files include a UTF-8 BOM for spreadsheet compatibility, and every ZIP includes both a human README and a machine-readable data dictionary.": "ローカルファイルに書き出します。CSV には表計算ソフト用の UTF-8 BOM が付きます。各 ZIP には README と機械可読のデータ辞書が含まれます。",
  "Use the available installer for your platform. The current development changes are separate from the published beta.6 installer.": "お使いの環境に対応するインストーラーを使用します。現在の開発中の変更は、公開済みの beta.6 インストーラーとは別です。",
