  "Every stimulus pool needs a name": "每个刺激池都需要名称",
  "Every stimulus pool needs a unique ID": "每个刺激池都需要唯一 ID",
  "Expected a Protocol Graph": "需要协议图",
  "External form URL is empty — paste a Google Forms, Qualtrics, or survey link": "外部表单 URL 为空，请粘贴 Google Forms、Qualtrics 或调查链接",
  "Frozen protocols cannot be edited.": "冻结的方案无法编辑。",
  "Graph commands cannot change a node ID": "图操作不能更改节点 ID",
  "Group ID is required": "组需要 ID",
  "Group IDs cannot be changed": "组 ID 无法更改",
  "Groups may contain presentation, response, condition, random split and loop nodes.": "组可包含呈现、响应、条件、随机分支和循环节点。",
  "Handler runtime components need a handlerId": "处理器运行时组件需要 handlerId",
  "Impossible condition order: no valid continuation.": "条件顺序无法生成：没有有效的后续排列。",
  "Impossible condition order: reduce repetitions or relax the consecutive-condition constraint.": "条件顺序无法生成：请减少重复次数或放宽连续条件限制。",
  "Include the enclosing loop in the group before randomizing it.": "随机化之前，请将外围循环包含在组中。",
